/**
 * Statistics domain model.
 *
 * Every snapshot carries an explicit `source` so the interface can never
 * present simulated numbers as a genuine Orion Drift read-out:
 *   simulated  -> generated by the mock integration or the seed script
 *   retrieved  -> parsed from an authorised Discord integration response
 *   unavailable -> no data could be collected
 */

import { z } from 'zod';

export const STAT_SOURCES = ['simulated', 'retrieved', 'unavailable'] as const;
export type StatSource = (typeof STAT_SOURCES)[number];

export const SERVER_STATUSES = ['online', 'degraded', 'offline'] as const;
export type ServerStatus = (typeof SERVER_STATUSES)[number];

export const MATCH_STATUSES = ['live', 'lobby', 'finished'] as const;
export type MatchStatus = (typeof MATCH_STATUSES)[number];

export const PLAYER_STATUSES = ['online', 'in-match', 'offline'] as const;
export type PlayerStatus = (typeof PLAYER_STATUSES)[number];

export const serverSnapshotSchema = z.object({
  id: z.string().min(1).max(80),
  name: z.string().min(1).max(120),
  region: z.string().max(60).default('Unknown'),
  status: z.enum(SERVER_STATUSES),
  playersOnline: z.number().int().min(0).max(1_000_000),
  maxPlayers: z.number().int().min(0).max(1_000_000),
  activeMatches: z.number().int().min(0).max(100_000).default(0),
  latencyMs: z.number().int().min(0).max(600_000).optional(),
  version: z.string().max(60).optional(),
});
export type ServerSnapshot = z.infer<typeof serverSnapshotSchema>;

export const matchSnapshotSchema = z.object({
  id: z.string().min(1).max(80),
  serverId: z.string().min(1).max(80),
  mode: z.string().min(1).max(60),
  map: z.string().max(80).optional(),
  players: z.number().int().min(0).max(10_000),
  maxPlayers: z.number().int().min(0).max(10_000),
  startedAt: z.string().min(1),
  status: z.enum(MATCH_STATUSES),
});
export type MatchSnapshot = z.infer<typeof matchSnapshotSchema>;

export const playerSnapshotSchema = z.object({
  externalId: z.string().min(1).max(120),
  displayName: z.string().min(1).max(120),
  platform: z.string().max(60).optional(),
  rank: z.string().max(60).optional(),
  status: z.enum(PLAYER_STATUSES).default('offline'),
  lastSeenAt: z.string().optional(),
});
export type PlayerSnapshot = z.infer<typeof playerSnapshotSchema>;

export const statisticsSummarySchema = z.object({
  playersOnline: z.number().int().min(0),
  activeMatches: z.number().int().min(0),
  activeServers: z.number().int().min(0),
  totalServers: z.number().int().min(0),
  healthScore: z.number().int().min(0).max(100),
});
export type StatisticsSummary = z.infer<typeof statisticsSummarySchema>;

export const playerDirectorySnapshotSchema = z.object({
  source: z.enum(['simulated', 'retrieved']),
  retrievedAt: z.string().min(1),
  players: z.array(playerSnapshotSchema).max(5_000),
  notes: z.string().max(2_000).optional(),
});
export type PlayerDirectorySnapshot = z.infer<typeof playerDirectorySnapshotSchema>;

export const statisticsSnapshotSchema = z.object({
  source: z.enum(['simulated', 'retrieved']),
  retrievedAt: z.string().min(1),
  summary: statisticsSummarySchema,
  servers: z.array(serverSnapshotSchema).max(200),
  matches: z.array(matchSnapshotSchema).max(1_000).default([]),
  players: z.array(playerSnapshotSchema).max(5_000).default([]),
  notes: z.string().max(2_000).optional(),
  warnings: z.array(z.string().max(500)).max(50).default([]),
});
export type StatisticsSnapshot = z.infer<typeof statisticsSnapshotSchema>;

export const STAT_SOURCE_LABELS: Record<StatSource, string> = {
  simulated: 'Simulated',
  retrieved: 'Retrieved',
  unavailable: 'Unavailable',
};

export const STAT_SOURCE_DESCRIPTIONS: Record<StatSource, string> = {
  simulated: 'Generated placeholder data. Not a genuine Orion Drift read-out.',
  retrieved:
    'Collected by the worker from an authorised integration and parsed by ORION CONTROL.',
  unavailable: 'No data is available. Nothing has been collected yet.',
};

/** Compute the summary block consistently for both real and simulated data. */
export function summarizeServers(servers: ServerSnapshot[]): StatisticsSummary {
  const totalServers = servers.length;
  const activeServers = servers.filter((server) => server.status !== 'offline').length;
  const playersOnline = servers.reduce((total, server) => total + server.playersOnline, 0);
  const activeMatches = servers.reduce((total, server) => total + server.activeMatches, 0);

  const capacity = servers.reduce((total, server) => total + server.maxPlayers, 0);
  const load = capacity > 0 ? playersOnline / capacity : 0;
  const availability = totalServers > 0 ? activeServers / totalServers : 0;
  let healthScore = Math.round(availability * 70 + Math.max(0, 1 - load) * 30);
  if (servers.some((server) => server.status === 'degraded')) healthScore -= 8;
  healthScore = Math.max(0, Math.min(100, healthScore));

  return { playersOnline, activeMatches, activeServers, totalServers, healthScore };
}

export function isStatisticsSnapshot(value: unknown): value is StatisticsSnapshot {
  return statisticsSnapshotSchema.safeParse(value).success;
}
